  1848  /*
  1849   * copy_word
  1850   * copies the next 'token' from 'from' into 'to', maximum len-1 characters.
  1851   * currently a token is anything separate by white space
  1852   * or within quotes (double or single) (i.e. "the red rose"
  1853   * is one token, \"the red rose\" is three tokens)
  1854   * a '\' character will allow a quote character to be treated
  1855   * as a regular character
  1856   * It returns a pointer to first non-white space after the end of the token
  1857   * being copied or to 0 if we reach the end.
  1858   * Note: Partially copied words (greater than len) still returns a !NULL ptr
  1859   * Note: partially copied words are, however, null terminated.
  1860   */
  1861
  1862  char           *
  1863  copy_nword(char *from, char *to, int len)
  1864  {
  1865      return NETSNMP_REMOVE_CONST(char *, copy_nword_const(from, to, len));
  1866  }
  1867
  1868  const char           *
  1869  copy_nword_const(const char *from, char *to, int len)
  1870  {
  1871      char            quote;
  1872      if (!from || !to)
  1873          return NULL;
  1874      if ((*from == '\"') || (*from == '\'')) {
  1875          quote = *(from++);
  1876          while ((*from != quote) && (*from != 0)) {
  1877              if ((*from == '\\') && (*(from + 1) != 0)) {
  1878                  if (len > 0) {  /* don't copy beyond len bytes */
  1879                      *to++ = *(from + 1);
  1880                      if (--len == 0)
  1881                          *(to - 1) = '\0';       /* null protect the last spot */
  1882                  }
  1883                  from = from + 2;
  1884              } else {
  1885                  if (len > 0) {  /* don't copy beyond len bytes */
  1886                      *to++ = *from++;
  1887                      if (--len == 0)
  1888                          *(to - 1) = '\0';       /* null protect the last spot */
  1889                  } else
  1890                      from++;
  1891              }
  1892          }
  1893          if (*from == 0) {
  1894              DEBUGMSGTL(("read_config_copy_word",
  1895                          "no end quote found in config string\n"));
  1896          } else
  1897              from++;
  1898      } else {
  1899          while (*from != 0 && !isspace((unsigned char)(*from))) {
  1900              if ((*from == '\\') && (*(from + 1) != 0)) {
  1901                  if (len > 0) {  /* don't copy beyond len bytes */
  1902                      *to++ = *(from + 1);
  1903                      if (--len == 0)
  1904                          *(to - 1) = '\0';       /* null protect the last spot */
  1905                  }
